mapper.update:
UPDATE manga_creative_dispatch_outbox
SET status = 'CLAIMED', claim_owner = #{claimOwner}, claim_until = #{claimUntil},
    attempts = attempts + 1, updated_by = #{updatedBy}
WHERE id = #{id}
  AND ((status = 'PENDING' AND (next_attempt_at IS NULL OR next_attempt_at <= #{now}))
    OR (status = 'CLAIMED' AND claim_until <= #{now}))

UPDATE manga_creative_dispatch_outbox
SET status = 'DISPATCHED', dispatched_at = #{dispatchedAt}, claim_until = NULL,
    next_attempt_at = NULL, last_error = NULL, updated_by = #{updatedBy}
WHERE id = #{id} AND status = 'CLAIMED' AND claim_owner = #{claimOwner}

UPDATE manga_creative_dispatch_outbox
SET status = 'PENDING', claim_owner = NULL, claim_until = NULL,
    next_attempt_at = #{nextAttemptAt}, last_error = #{lastError}, updated_by = #{updatedBy}
WHERE id = #{id} AND status = 'CLAIMED' AND claim_owner = #{claimOwner}
